22	constexpr const char_t *const kBuiltIn = "built-in";
23	constexpr const char_t *const kSoSuffix = ".so";
24	constexpr const char_t *const kRt2SoSuffix = "rt2.0.so";
25	constexpr const char_t *const kCtSoSuffix = "ct.so";
26	constexpr const char_t *const kRtSoSuffix = "rt.so";
27	constexpr const char_t *const kLegacySoSuffix = "_legacy.so";
28	const std::string kOpsProtoPath = "/op_proto/lib/";
29	const std::string kOpsGraphPath = "/op_graph/lib/";
30	const std::string kOpMasterPath = "/op_impl/ai_core/tbe/op_tiling/lib/";
31	const std::string kOpHostPath = "/op_impl/ai_core/tbe/op_host/lib/";
32	
33	using GetPathFunc = std::function<Status(std::string &)>;
34	const std::map<gert::OppImplVersionTag, GetPathFunc> kVersion2GetProtoPathFunc = {
35	    {gert::OppImplVersionTag::kOpp, [](std::string &path) { return metadef::PluginManager::GetOpsProtoPath(path); }},
36	    {gert::OppImplVersionTag::kOppKernel,
37	     [](std::string &path) { return metadef::PluginManager::GetUpgradedOpsProtoPath(path); }}};
38	
39	const std::map<gert::OppImplVersionTag, GetPathFunc> kVersion2GetMasterPathFunc = {
40	    {gert::OppImplVersionTag::kOpp,
41	     [](std::string &path) { return metadef::PluginManager::GetOpTilingForwardOrderPath(path); }},
42	    {gert::OppImplVersionTag::kOppKernel,
43	     [](std::string &path) { return metadef::PluginManager::GetUpgradedOpMasterPath(path); }}};
44	
45	gert::OppSoDesc *GetOppSoDescPtr(std::vector<std::pair<std::string, gert::OppSoDesc>> &vec,
46	                                 const std::string &package_name) {
47	  for (auto &item : vec) {
48	    if (item.first == package_name) {
49	      return &item.second;
50	    }
51	  }
52	  return nullptr;
53	}
54	
55	void GetOppSoList(const std::string &opp_so_path, const std::vector<std::string> &so_suffix_list,
56	                  std::vector<std::pair<std::string, gert::OppSoDesc>> &package_to_opp_so_desc,
57	                  gert::OppImplVersionTag opp_version_tag) {
58	  std::vector<std::string> so_list;
59	  for (auto &so_suffix : so_suffix_list) {
60	    metadef::PluginManager::GetFileListWithSuffix(opp_so_path, so_suffix, so_list);
61	  }
62	  // 排序，将"_legacy.so"移到到最后
63	  (void)std::stable_partition(so_list.begin(), so_list.end(), [](const std::string &so_name) {
64	    return so_name.size() < std::strlen(kLegacySoSuffix) ||
65	           so_name.compare((so_name.size() - std::strlen(kLegacySoSuffix)), std::strlen(kLegacySoSuffix),
66	                           kLegacySoSuffix) != 0;
67	  });
68	  for (const auto &so_name : so_list) {
69	    GELOGD("GetOppSoList from path %s, so_name is %s", opp_so_path.c_str(), so_name.c_str());
70	  }
71	
72	  // 合并到so_list到package_to_opp_so_desc对应的值中
73	  std::string package_name = metadef::PluginManager::GetSoPackageName(opp_so_path);
74	  if (opp_version_tag >= gert::OppImplVersionTag::kVersionEnd) {
75	    GELOGE(ge::FAILED, "Invalid opp_impl_version: %d", static_cast<int32_t>(opp_version_tag));
76	    return;
77	  }
78	  std::vector<ge::AscendString> new_so_path_vector;
79	  new_so_path_vector.reserve(so_list.size());
80	  (void)std::transform(so_list.begin(), so_list.end(), std::back_inserter(new_so_path_vector),
81	                       [](const std::string &s) { return ge::AscendString(s.c_str()); });
82	
83	  auto opp_so_desc_ptr = GetOppSoDescPtr(package_to_opp_so_desc, package_name);
84	  if (opp_so_desc_ptr == nullptr) {
85	    GELOGI("Created new opp so list for package [%s], so num is [%zu], opp_impl_version: [%d]", package_name.c_str(),
86	           new_so_path_vector.size(), static_cast<int32_t>(opp_version_tag));
87	    // 无则创建
88	    gert::OppSoDesc opp_so_desc = gert::OppSoDesc(new_so_path_vector, AscendString(package_name.c_str()));
89	    (void)package_to_opp_so_desc.emplace_back(package_name, opp_so_desc);
90	  } else {
91	    GELOGI("Merged opp so list for package [%s], so num is [%zu], opp_impl_version: [%d]", package_name.c_str(),
92	           so_list.size(), static_cast<int32_t>(opp_version_tag));
93	    // 有则追加合并
94	    auto existing_so_path_vector = opp_so_desc_ptr->GetSoPaths();
95	    (void)existing_so_path_vector.insert(existing_so_path_vector.end(), new_so_path_vector.begin(),
96	                                         new_so_path_vector.end());
97	    *opp_so_desc_ptr = gert::OppSoDesc(existing_so_path_vector, AscendString(package_name.c_str()));
98	  }
99	}
100	}  // namespace
101	
102	void OppSoManager::LoadSoAndInitDefault(const std::vector<AscendString> &so_list,
103	                                        gert::OppImplVersionTag opp_version_tag,
104	                                        const std::string &package_name) const {
105	  GELOGI("Start to LoadSoAndInitDefault, opp_impl_version: %d, package name:%s", static_cast<int32_t>(opp_version_tag),
106	         package_name.c_str());
107	  gert::OppSoDesc opp_so_desc(so_list, AscendString(package_name.c_str()));
108	  auto space_registry_v2 = gert::DefaultOpImplSpaceRegistryV2::GetInstance().GetSpaceRegistry(opp_version_tag);
109	  if (space_registry_v2 == nullptr) {
110	    space_registry_v2 = std::make_shared<gert::OpImplSpaceRegistryV2>();
111	    (void)gert::DefaultOpImplSpaceRegistryV2::GetInstance().SetSpaceRegistry(space_registry_v2, opp_version_tag);
112	  }
113	
114	  if (space_registry_v2->AddSoToRegistry(opp_so_desc) != ge::SUCCESS) {
115	    GELOGW("AddSoToRegistry failed, package name is %s", package_name.c_str());
116	  }
117	}
118	
119	void OppSoManager::LoadOpsProtoPackage() const {
120	  const std::lock_guard<std::mutex> lock(mutex_);
121	  bool is_split = metadef::PluginManager::IsSplitOpp();
122	  GELOGI("Start to load ops proto package, is_split:[%d].", is_split);
123	  for (int32_t v = 0; v < static_cast<int32_t>(gert::OppImplVersionTag::kVersionEnd); ++v) {
124	    const auto version = static_cast<gert::OppImplVersionTag>(v);
125	    std::vector<std::pair<std::string, gert::OppSoDesc>> package_to_opp_so_desc;
126	    is_split = metadef::PluginManager::IsSplitOpp();
127	    if (version == gert::OppImplVersionTag::kOppKernel && !is_split) {
128	      // 非拆分模式下，无需加载OppKernel目录下so
129	      continue;
130	    }
131	    LoadOpsProtoSo(version, package_to_opp_so_desc, is_split);
132	    for (const auto &item : package_to_opp_so_desc) {
133	      auto package_name = item.first;
134	      auto so_list_opp = item.second;
135	      LoadSoAndInitDefault(so_list_opp.GetSoPaths(), version, package_name);
136	    }
137	  }
138	}
139	
140	void OppSoManager::LoadOppPackage() const {
141	  const std::lock_guard<std::mutex> lock(mutex_);
142	  for (int32_t v = 0; v < static_cast<int32_t>(gert::OppImplVersionTag::kVersionEnd); ++v) {
143	    const auto version = static_cast<gert::OppImplVersionTag>(v);
144	    std::vector<std::pair<std::string, gert::OppSoDesc>> package_to_opp_so_desc_opp;
145	    const bool is_split = metadef::PluginManager::IsSplitOpp();
146	    if (version == gert::OppImplVersionTag::kOppKernel && !is_split) {
147	      // 非拆分模式下，无需加载OppKernel目录下so
148	      continue;
149	    }
150	    GELOGI("Start to load opp package, opp_impl_version: %d, is_split:[%d].", v, is_split);
151	    LoadOpsProtoSo(version, package_to_opp_so_desc_opp, is_split);
152	    LoadOpMasterSo(version, package_to_opp_so_desc_opp, is_split);
153	    for (const auto &item : package_to_opp_so_desc_opp) {
154	      auto package_name = item.first;
155	      auto so_list_opp = item.second;
156	      auto so_paths = so_list_opp.GetSoPaths();
157	      // 将_legacy.so后缀的so移到最后，保持其他成员顺序不变
158	      (void)std::stable_partition(so_paths.begin(), so_paths.end(), [](const ge::AscendString &so_name) {
159	        if (so_name.GetString() != nullptr) {
160	          std::string so_name_str = so_name.GetString();
161	          return so_name_str.size() < std::strlen(kLegacySoSuffix) ||
162	                 so_name_str.compare((so_name_str.size() - std::strlen(kLegacySoSuffix)), std::strlen(kLegacySoSuffix),
163	                                     kLegacySoSuffix) != 0;
164	        }
165	        return true;
166	      });
167	      for (const auto &so_name : so_paths) {
168	        GELOGI("[LoadOppPackage]load so, so_name is %s", so_name.GetString());
169	      }
170	      so_list_opp = gert::OppSoDesc(so_paths, AscendString(package_name.c_str()));
171	      LoadSoAndInitDefault(so_list_opp.GetSoPaths(), version, package_name);
172	    }
173	  }
174	}
175	
176	void OppSoManager::LoadOpsProtoSo(gert::OppImplVersionTag version,
177	                                  std::vector<std::pair<std::string, gert::OppSoDesc>> &package_to_opp_so_desc,
178	                                  bool is_split) const {
179	  std::string ops_proto_path;
180	  auto it = kVersion2GetProtoPathFunc.find(version);
181	  if (it == kVersion2GetProtoPathFunc.end()) {
182	    GELOGW("[LoadOpsProtoSo] Not find get ops proto function with version:%d", static_cast<int32_t>(version));
183	    return;
184	  }
185	  GELOGI("Start to load ops proto package, opp_impl_version: %d, is_split:[%d].", static_cast<int32_t>(version),
186	         is_split);
187	  if (it->second(ops_proto_path) != ge::SUCCESS) {
188	    GELOGW("[LoadOpsProtoSo] Get ops proto path failed, opp_impl_version: %d", static_cast<int32_t>(version));
189	    return;
190	  }
191	
192	  std::string os_type;
193	  std::string cpu_type;
194	  metadef::PluginManager::GetCurEnvPackageOsAndCpuType(os_type, cpu_type);
195	
196	  std::vector<std::string> v_path;
197	  metadef::PluginManager::SplitPath(ops_proto_path, v_path);
198	  for (size_t i = 0UL; i < v_path.size(); ++i) {
199	    if (v_path[i].back() != '/') {
200	      v_path[i] += '/';
201	    }
202	    std::array<char_t, MMPA_MAX_PATH> resolved_path{};
203	    // 加载自定义算子so
204	    const auto idx = v_path[i].find(kBuiltIn);
205	    if (idx == std::string::npos) {
206	      std::string path = v_path[i] + "lib/" + os_type + "/" + cpu_type + "/";
207	      const INT32 result = mmRealPath(path.c_str(), &(resolved_path[0U]), MMPA_MAX_PATH);
208	      if (result != EN_OK) {
209	        GELOGW("[FindSo][Check] Get path with os&cpu type [%s] failed, reason:%s", path.c_str(), strerror(errno));
210	        continue;
211	      }
212	      GetOppSoList(path, {kSoSuffix}, package_to_opp_so_desc, version);
213	      continue;
214	    }
215	    // 加载built-in算子so
216	    std::string path = v_path[i].substr(0, idx) + kBuiltIn;
217	    bool is_sub_pkg = false;
218	    path = metadef::PluginManager::GetOppPkgPath(path, kOpsProtoPath, kOpsGraphPath, os_type + "/" + cpu_type + "/",
219	                                                 is_sub_pkg);
220	    if (is_sub_pkg) {
221	      GetOppSoList(path, {kSoSuffix}, package_to_opp_so_desc, version);
222	    } else {
223	      if (mmRealPath(path.c_str(), &(resolved_path[0U]), MMPA_MAX_PATH) != EN_OK) {
224	        GELOGW("[FindSo][Check] Get path with os&cpu type [%s] failed, reason:%s", path.c_str(), strerror(errno));
225	        continue;
226	      }
227	      if (is_split) {
228	        GetOppSoList(path, {kCtSoSuffix, kRtSoSuffix}, package_to_opp_so_desc, version);
229	      } else {
230	        GetOppSoList(path, {kCtSoSuffix, kRt2SoSuffix}, package_to_opp_so_desc, version);
231	      }
232	    }
233	  }
234	}
235	
236	void OppSoManager::LoadOpMasterSo(gert::OppImplVersionTag version,
237	                                  std::vector<std::pair<std::string, gert::OppSoDesc>> &package_to_opp_so_desc,
238	                                  bool is_split) const {
239	  std::string op_tiling_path;
240	  auto it = kVersion2GetMasterPathFunc.find(version);
241	  if (it == kVersion2GetMasterPathFunc.end()) {
242	    GELOGW("[LoadOpsProtoSo] Not find get ops proto function with version:%d", static_cast<int32_t>(version));
243	    return;
244	  }
245	  GELOGI("Start to load ops master package, opp_impl_version: %d, is_split:[%d].", static_cast<int32_t>(version),
246	         is_split);
247	  if (it->second(op_tiling_path) != ge::SUCCESS) {
248	    GELOGW("[LoadOpsProtoSo] Get ops proto path failed, opp_impl_version: %d", static_cast<int32_t>(version));
249	    return;
250	  }
251	
252	  std::string os_type;
253	  std::string cpu_type;
254	  metadef::PluginManager::GetCurEnvPackageOsAndCpuType(os_type, cpu_type);
255	
256	  std::vector<std::string> path_vec;
257	  metadef::PluginManager::SplitPath(op_tiling_path, path_vec);
258	  for (auto &path : path_vec) {
259	    if (path.back() != '/') {
260	      path += '/';
261	    }
262	    // 加载自定义算子so
263	    std::array<char_t, MMPA_MAX_PATH> resolved_path{};
264	    const auto idx = path.find(kBuiltIn);
265	    if (idx == std::string::npos) {
266	      std::string root_path = path + "op_master/lib/" + os_type + "/" + cpu_type + "/";
267	      if (mmRealPath(root_path.c_str(), &(resolved_path[0U]), MMPA_MAX_PATH) != EN_OK) {
268	        GELOGW("Get path with op_master path [%s] failed, reason:%s", root_path.c_str(), strerror(errno));
269	        root_path = path + "op_tiling/lib/" + os_type + "/" + cpu_type + "/";
270	        if (mmRealPath(root_path.c_str(), &(resolved_path[0U]), MMPA_MAX_PATH) != EN_OK) {
271	          GELOGW("Get path with op_tiling path [%s] failed, reason:%s", root_path.c_str(), strerror(errno));
272	          continue;
273	        }
274	      }
275	      GetOppSoList(root_path, {kSoSuffix}, package_to_opp_so_desc, version);
276	      continue;
277	    }
278	    // 加载built-in算子so
279	    std::string root_path = path.substr(0, idx) + kBuiltIn;
280	    bool is_sub_pkg = false;
281	    root_path = metadef::PluginManager::GetOppPkgPath(root_path, kOpMasterPath, kOpHostPath,
282	                                                      os_type + "/" + cpu_type + "/", is_sub_pkg);
283	    if (is_sub_pkg) {
284	      GetOppSoList(root_path, {kSoSuffix}, package_to_opp_so_desc, version);
285	    } else {
286	      if (mmRealPath(root_path.c_str(), &(resolved_path[0U]), MMPA_MAX_PATH) != EN_OK) {
287	        GELOGW("Get path with op_tiling path [%s] failed, reason:%s", root_path.c_str(), strerror(errno));
288	        continue;
289	      }
290	      if (is_split) {
291	        GetOppSoList(root_path, {kCtSoSuffix, kRtSoSuffix}, package_to_opp_so_desc, version);
292	      } else {
293	        GetOppSoList(root_path, {kCtSoSuffix, kRt2SoSuffix}, package_to_opp_so_desc, version);
294	      }
295	    }
296	  }
297	}
298	
299	OppSoManager &OppSoManager::GetInstance() {
300	  static OppSoManager instance;
301	  return instance;
302	}
303	}  // namespace ge
