134	      std::string subDir = currentPath.substr(0, pos);
135	      const int32_t status = mkdir(subDir.c_str(), static_cast<mode_t>(S_IRWXU) | static_cast<mode_t>(S_IRWXG));
136	      if (status == -1 && errno != EEXIST) {
137	        return false;
138	      }
139	      pos = currentPath.find('/', pos + 1U);
140	    }
141	    const int32_t status = mkdir(currentPath.c_str(), static_cast<mode_t>(S_IRWXU) | static_cast<mode_t>(S_IRWXG));
142	    if (status == -1 && errno != EEXIST) {
143	      return false;
144	    }
145	    GELOGD("Running CreateDirectory Succeed.");
146	    return true;
147	  }
148	}
