207	bool RemoveDirectoryRecursively(const std::string &path) {
208	  GELOGD("Running RemoveDirectoryRecursively.");
209	  DIR *dir = opendir(path.c_str());
210	  if (dir == nullptr) {
211	    const int32_t currentErr = errno;
212	    if (currentErr == ENOENT) {
213	      GELOGW("Directory does not exist: %s", path.c_str());
214	      return true;
215	    } else {
216	      GELOGW("Failed to open directory: %s", path.c_str());
