220	  dirent *entry = readdir(dir);
221	  while (entry != nullptr) {
222	    std::string entryPath = path + "/" + entry->d_name;
223	    if (static_cast<int32_t>(entry->d_type) == DT_DIR) {
224	      if (std::string(entry->d_name) != "." && std::string(entry->d_name) != "..") {
225	        if (!RemoveDirectoryRecursively(entryPath)) {
226	          GELOGW("Failed to remove subdirectory: %s", entryPath.c_str());
227	          CheckCloseDir(dir, __FILE__, __LINE__, __FUNCTION__);
228	          return false;
229	        }
230	        GELOGI("Successfully remove subdirectory: %s", entryPath.c_str());
231	      }
232	    } else {
233	      if (unlink(entryPath.c_str()) != 0) {
234	        GELOGW("Failed to unlink file: %s", entryPath.c_str());
235	        CheckCloseDir(dir, __FILE__, __LINE__, __FUNCTION__);
236	        return false;
237	      }
238	      GELOGI("Successfully remove linkpath: %s", entryPath.c_str());
239	    }
240	    entry = readdir(dir);
241	  }
242	  CheckCloseDir(dir, __FILE__, __LINE__, __FUNCTION__);
243	  const bool result = (rmdir(path.c_str()) == 0);
244	  return result;
