308	uint32_t OpBinInfo::Generate(ge::AscendString *opLibPath, const std::string &targetPath) {
309	  for (const auto &fileInfo : opInfo_) {
310	    std::string fileName = std::get<0>(fileInfo).GetString();
311	    std::string filePath = std::get<1>(fileInfo).GetString();
312	    const uint8_t *start = std::get<2>(fileInfo);
313	    const uint8_t *end = std::get<3>(fileInfo);
314	    std::string fullPath = (basePath_) + "/" + filePath + "/" + fileName;
315	    if (!CreateDirectory((basePath_) + "/" + filePath)) {
316	      GELOGE(ge::FAILED, "Failed to create subdirectory: %s", filePath.c_str());
317	      return 1;
318	    }
319	    WriteBinaryFile(fullPath, start, end);
320	  }
321	  GELOGI("Get OpLibPath is %s", (basePath_ + opType_).c_str());
322	
323	  std::string arch = "";
324	  const bool ret = GetSystemArchitecture(arch);
325	  if (!ret) {
326	    GELOGE(ge::FAILED, "Failed to get system architecture name");
327	    return 1;
328	  }
329	
330	  std::string resolvedPath = RealPath(targetPath.c_str());
331	  if (resolvedPath.empty()) {
332	    GELOGE(ge::FAILED, "Failed to resolve libcust_opapi.so path.");
333	    return 1;
334	  }
335	  std::string targetResPath = resolvedPath;
336	  GELOGI("Resolve libcust_opapi.so path is: %s", targetResPath.c_str());
337	  std::string opmasterPath =
338	      basePath_ + opType_ + "/op_impl/ai_core/tbe/op_tiling/lib/linux/" + arch + "/libcust_opmaster_rt2.0.so";
339	  if (!CreateSymlink(targetResPath, opmasterPath)) {
340	    GELOGE(ge::FAILED, "Failed to create symlink for libcust_opmaster_rt2.0.so");
341	    return 1;
342	  }
343	  std::string opsprotoPath = basePath_ + opType_ + "/op_proto/lib/linux/" + arch + "/libcust_opsproto_rt2.0.so";
344	  if (!CreateSymlink(targetResPath, opsprotoPath)) {
345	    GELOGE(ge::FAILED, "Failed to create symlink for libcust_opsproto_rt2.0.so");
346	    return 1;
347	  }
348	  std::string optilingPath = basePath_ + opType_ + "/op_impl/ai_core/tbe/op_tiling/liboptiling.so";
349	  if (!CreateSymlink(targetResPath, optilingPath)) {
350	    GELOGE(ge::FAILED, "Failed to create symlink for liboptiling.so");
351	    return 1;
352	  }
353	  *opLibPath = ge::AscendString((basePath_ + opType_).c_str());
354	  return 0;
355	}
356	
357	bool OpBinInfo::Check(const std::string &path) {
358	  Elf64_Ehdr ehdr;
359	  std::ifstream file(path, std::ios::binary);
360	  const std::streamsize sizeEhdr = static_cast<std::streamsize>(sizeof(ehdr));
361	  file.read(reinterpret_cast<char *>(&ehdr), sizeEhdr);
362	  file.seekg(static_cast<std::streamoff>(ehdr.e_phoff));
363	  std::vector<Elf64_Phdr> phdrs(static_cast<size_t>(ehdr.e_phnum));
364	  const std::streamsize sizePhnum = static_cast<std::streamsize>(sizeof(Elf64_Phdr));
365	  if (!file.read(reinterpret_cast<char *>(phdrs.data()), static_cast<long>(ehdr.e_phnum) * sizePhnum)) {
366	    file.close();
367	    GELOGE(ge::FAILED, "Failed to read file %s phdrs.", path.c_str());
368	    return false;
369	  }
370	  if (memcmp(ehdr.e_ident,
371	             "\x7F"
372	             "ELF",
373	             kOpsFour) != 0) {
374	    file.close();
375	    GELOGE(ge::FAILED, "File %s is not a valid ELF file.", path.c_str());
376	    return false;
377	  }
378	  if (ehdr.e_type != ET_DYN) {
379	    file.close();
380	    GELOGE(ge::FAILED, "File %s is not a shared library, the e_type is not ET_DYN.", path.c_str());
381	    return false;
382	  }
383	  for (const auto &phdr : phdrs) {
384	    if (phdr.p_type == PT_INTERP) {
385	      file.close();
386	      GELOGE(ge::FAILED, "File %s is an executable with PT_INTERP segment. Not a shared library.", path.c_str());
387	      return false;
388	    }
389	  }
390	  file.close();
391	  return true;
392	}
393	}  // namespace ops
