87	ge::graphStatus OpImplSpaceRegistryImpl::AddSoToRegistry(const OppSoDesc &so_desc) {
88	  if (so_desc.GetPackageName() == "main_exe") {
89	    return AddMainExeToRegistry(so_desc);
90	  }
91	  auto types_to_impl_from_holder = std::map<OpImplRegisterV2::OpType, OpImplKernelRegistry::OpImplFunctionsV2>();
92	  for (const auto &so_path_ascend_string : so_desc.GetSoPaths()) {
93	    auto so_path = so_path_ascend_string.GetString();
94	    GELOGI("Start to AddSoToRegistry so_path:%s, package name %s", so_path, so_desc.GetPackageName().GetString());
95	    uint32_t len = 0U;
96	    const auto so_data = metadef::GetBinDataFromFile(std::string(so_path), len);
97	    GE_ASSERT_NOTNULL(so_data);
98	    const auto create_func = [&types_to_impl_from_holder, so_path, so_desc]() -> OpImplRegistryHolderPtr {
99	      void *const handle = mmDlopen(so_path, static_cast<int32_t>(static_cast<uint32_t>(MMPA_RTLD_NOW) |
100	                                                                  static_cast<uint32_t>(MMPA_RTLD_GLOBAL)));
101	      if (handle == nullptr) {
102	        // 为兼顾兼容性和维测能力，此处算子so加载失败打印ERROR日志，并打屏提示用户
103	        std::stringstream ss;
104	        ss << "Failed to load " << so_desc.GetPackageName().GetString() << " library `" << so_path << "` via dlopen."
105	           << std::endl;
106	        ss << "This may cause missing functionality or reduced precision in related operations." << std::endl;
107	        ss << "Next steps:" << std::endl;
108	        ss << "  1. Diagnose: Review the specific error cause below." << std::endl;
109	        ss << "  2. Resolve: Ensure correct path, version, and dependencies (e.g., missing libraries)." << std::endl;
110	        ss << "  3. Refer to: "
111	              "https://gitcode.com/cann/ge/wiki/"
112	              "GE%E5%B8%B8%E8%A7%81%E9%97%AE%E9%A2%98%E5%AE%9A%E4%BD%8D%E6%89%8B%E5%86%8C.md#4-%E7%AE%97%E5%AD%90so%E5%"
113	              "8A%A0%E8%BD%BD%E5%A4%B1%E8%B4%A5%E7%B1%BB%E9%97%AE%E9%A2%98 for further troubleshooting."
114	           << std::endl;
115	        ss << "Error detail: " << mmDlerror() << std::endl;
116	        GELOGE(ge::GRAPH_FAILED, "%s", ss.str().c_str());
117	        std::cout << "[ERROR] " << ss.str() << std::endl;
118	        return nullptr;
119	      }
120	      const std::function<void()> callback = [&handle]() { CloseHandle(handle); };
121	      GE_DISMISSABLE_GUARD(close_handle, callback);
122	      auto om_registry_holder = ge::MakeShared<gert::OpImplRegistryHolder>();
123	      if (om_registry_holder == nullptr) {
124	        return nullptr;
125	      }
126	      if (om_registry_holder->GetOpImplFunctionsByHandle(handle, so_path) != ge::GRAPH_SUCCESS) {
127	        GELOGW("Failed to get funcs from so!");
128	        return nullptr;
129	      }
130	      for (const auto &type : om_registry_holder->GetTypesToImpl()) {
131	        types_to_impl_from_holder[type.first] = type.second;
132	      }
133	      om_registry_holder->SetHandle(handle);
134	      GE_DISMISS_GUARD(close_handle);
135	      return om_registry_holder;
136	    };
137	
138	    const std::string str_so_data(so_data.get(), static_cast<size_t>(len));
139	    const auto registry_holder = OpImplRegistryHolderManager::GetInstance().GetOrCreateOpImplRegistryHolder(
140	        std::string(so_path), str_so_data, create_func);
141	    if (registry_holder == nullptr) {
142	      GELOGW("Nothing in so, so_path:%s, package name %s", so_path, so_desc.GetPackageName().GetString());
143	      continue;
144	    }
145	    GE_ASSERT_GRAPH_SUCCESS(AddRegistry(registry_holder));
146	    GELOGI("Save so symbol and handle in path[%s] successfully!", so_path);
147	  }
148	
149	  const auto package_name = so_desc.GetPackageName().GetString();
150	  // package_name为空或为"built-in"时，不进行算子交付件校验
151	  if (package_name == nullptr || package_name[0] == '\0' || strcmp(package_name, kBuiltIn) == 0) {
152	    return ge::GRAPH_SUCCESS;
153	  }
154	  GELOGI("Start to check missing implementation for custom op package [%s]", so_desc.GetPackageName().GetString());
155	  for (const auto &kv : types_to_impl_from_holder) {
156	    const auto &op_type = kv.first;
157	    const auto &funcs = kv.second;
158	    const char *op_type_str = op_type.GetString();
159	
160	    if (funcs.tiling == nullptr) {
161	      GELOGW("[MissOpImplementation] op [%s] has no tiling", op_type_str);
162	    }
163	  }
164	
165	  return ge::GRAPH_SUCCESS;
166	}
